/* 全部控件创建完成后统一注册；每次新建屏幕只调用一次。 */
void aido_event_init_menulight(aidogui_ui_t * ui)
{
    aido_flow_observe(aidogui_ui.menulight.root);
    aido_flow_observe(aidogui_ui.menulight.TopRule);
    aido_flow_observe(aidogui_ui.menulight.BrandMarkRing);
    aido_flow_observe(aidogui_ui.menulight.BrandMarkCore);
    aido_flow_observe(aidogui_ui.menulight.StatusBattery);
    aido_flow_observe(aidogui_ui.menulight.StatusBluetooth);
    aido_flow_observe(aidogui_ui.menulight.StatusWifi);
    aido_flow_observe(aidogui_ui.menulight.MenuTitle);
    aido_flow_observe(aidogui_ui.menulight.LightSensorIcon);
    aido_flow_observe(aidogui_ui.menulight.LightSensorText);
    aido_flow_observe(aidogui_ui.menulight.SensorHit);
    aido_flow_observe(aidogui_ui.menulight.LightSensor);
    aido_flow_observe(aidogui_ui.menulight.LightNetworkIcon);
    aido_flow_observe(aidogui_ui.menulight.LightNetworkText);
    aido_flow_observe(aidogui_ui.menulight.NetworkHit);
    aido_flow_observe(aidogui_ui.menulight.LightNetwork);
    aido_flow_observe(aidogui_ui.menulight.LightBleIcon);
    aido_flow_observe(aidogui_ui.menulight.LightBleText);
    aido_flow_observe(aidogui_ui.menulight.BleHit);
    aido_flow_observe(aidogui_ui.menulight.LightBle);
    aido_flow_observe(aidogui_ui.menulight.LightAudioIcon);
    aido_flow_observe(aidogui_ui.menulight.LightAudioText);
    aido_flow_observe(aidogui_ui.menulight.AudioHit);
    aido_flow_observe(aidogui_ui.menulight.LightAudio);
    aido_flow_observe(aidogui_ui.menulight.LightDisplayIcon);
    aido_flow_observe(aidogui_ui.menulight.LightDisplayText);
    aido_flow_observe(aidogui_ui.menulight.DisplayHit);
    aido_flow_observe(aidogui_ui.menulight.LightDisplay);
    aido_flow_observe(aidogui_ui.menulight.LightSystemIcon);
    aido_flow_observe(aidogui_ui.menulight.LightSystemText);
    aido_flow_observe(aidogui_ui.menulight.SystemHit);
    aido_flow_observe(aidogui_ui.menulight.LightSystem);
    aido_flow_observe(aidogui_ui.menulight.MenuLightStage);
    lv_obj_remove_event_cb(ui->menulight.LightSensor, LightSensor_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightSensor, LightSensor_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.SensorHit, SensorHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.SensorHit, SensorHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.LightNetwork, LightNetwork_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightNetwork, LightNetwork_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.NetworkHit, NetworkHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.NetworkHit, NetworkHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.LightBle, LightBle_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightBle, LightBle_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.BleHit, BleHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.BleHit, BleHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.LightAudio, LightAudio_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightAudio, LightAudio_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.AudioHit, AudioHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.AudioHit, AudioHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.LightDisplay, LightDisplay_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightDisplay, LightDisplay_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.DisplayHit, DisplayHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.DisplayHit, DisplayHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.LightSystem, LightSystem_event_handler);
    lv_obj_add_event_cb(ui->menulight.LightSystem, LightSystem_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menulight.SystemHit, SystemHit_event_handler);
    lv_obj_add_event_cb(ui->menulight.SystemHit, SystemHit_event_handler, LV_EVENT_ALL, ui);
}

